/** Independent released callback boxes; no registry/world setup or geometry substitution. */
public final class NativeRampGeometryChecks {
 private static BlockPos position(JsonArray p){return new BlockPos(p.get(0).getAsInt(),p.get(1).getAsInt(),p.get(2).getAsInt());}
 private static Direction facing(JsonObject row){int meta=row.get("meta").getAsInt();if(row.get("block").getAsString().endsWith("_slab")){int face=meta&7;var scan=face<6?Direction.from3DDataValue(face):Direction.NORTH;return scan.getAxis().isVertical()?Direction.NORTH:scan;}return (meta&8)!=0?Direction.NORTH:Direction.from2DDataValue(meta&3);}
 public static void main(String[] args)throws Exception{int rows=0,snapshots=0,boxes=0,drift=0;double maximum=0;boolean collisions=args.length>1&&args[1].equals("--collision");long maximumUnionNanos=0;int maximumUnionBytes=0;try(var input=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(args[0]))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=input.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();int material=row.get("material").getAsInt();for(var stateElement:row.getAsJsonArray("states")){var state=stateElement.getAsJsonObject();var owner=TagParser.parseTag(state.get("saved").getAsString());long time=owner.getLong("LastStepTick");for(var partElement:state.getAsJsonArray("parts")){var part=partElement.getAsJsonObject();var tag=TagParser.parseTag(part.get("saved").getAsString());var cell=position(part.getAsJsonArray("position"));var origins=new ArrayList<NativeRampGeometry.Origin>();var list=tag.getList("Origins",Tag.TAG_COMPOUND);for(int i=0;i<list.size();i++){var origin=list.getCompound(i);List<AABB> shapes=material==3?List.of(new AABB(0,0,0,1,.5,1),new AABB(0,.5,0,1,1,.5)):List.of(new AABB(0,tag.getDouble("Low"),0,1,tag.getDouble("High"),1));origins.add(new NativeRampGeometry.Origin(new BlockPos(origin.getInt("X"),origin.getInt("Y"),origin.getInt("Z")),shapes));}
    var spec=new NativeRampGeometry.Spec(cell,facing(row),tag.getInt("SourceY"),tag.getInt("Row"),tag.getInt("Length"),tag.getInt("TreadPixels"),tag.getDouble("Low"),tag.getDouble("High"),tag.getInt("StartOffsetHalfSteps")/2D,tag.getInt("EndOffsetHalfSteps")/2D,tag.getBoolean("Elevator"),tag.getInt("TravelAxis"),tag.getBoolean("ExtendSegments"),tag.getInt("SpeedMode")==0,tag.getInt("RampInterpolation"),tag.getBoolean("RampVerticalLayout"),tag.getBoolean("MoatMode"),material==3,origins);
    double pose=tag.getBoolean("Moving")?ControllerPlatform.pose(tag.getDouble("StartPose"),tag.contains("RampTargetPose",Tag.TAG_DOUBLE)?tag.getDouble("RampTargetPose"):tag.getBoolean("Open")?1:0,time-tag.getLong("StartTick")+.25,tag.getInt("Duration")):tag.getDouble("StartPose");var actual=NativeRampGeometry.snapshot(spec,pose);if(actual.retainedBytes()<160L+160L*actual.pieces().size()||actual.retainedBytes()>4L*1024*1024)throw new AssertionError("Snapshot retained-byte accounting");if(collisions){var components=actual.pieces().stream().map(NativeRampGeometry.Piece::box).toList();long at=System.nanoTime();var shape=com.vandorlabs.neoforge.NativeVoxelShapes.union(components,4*1024*1024,1e-8);maximumUnionNanos=Math.max(maximumUnionNanos,System.nanoTime()-at);int bytes=com.vandorlabs.neoforge.NativeVoxelShapes.retainedCost(shape,components.size());maximumUnionBytes=Math.max(maximumUnionBytes,bytes);if(bytes+actual.retainedBytes()>4*1024*1024)throw new AssertionError("Part publication retained budget");if(components.isEmpty()!=shape.isEmpty())throw new AssertionError("Part empty shape mismatch");var unionBoxes=shape.toAabbs();for(var component:components){double x=(component.minX+component.maxX)*.5,y=(component.minY+component.maxY)*.5,z=(component.minZ+component.maxZ)*.5;if(unionBoxes.stream().noneMatch(b->b.contains(x,y,z)))throw new AssertionError("Part union lost source component row="+rows+" cell="+cell);}if(!components.isEmpty()&&!shape.bounds().equals(actual.bounds()))throw new AssertionError("Part exact union bounds");}var expected=part.getAsJsonArray("boxes");if(actual.pieces().size()!=expected.size())throw new AssertionError("Released Ramp boxes row="+rows+" mode="+row.get("mode")+" material="+material+" cell="+cell+" pose="+pose+" expected="+expected.size()+" actual="+actual.pieces().size());for(int i=0;i<expected.size();i++){var b=actual.pieces().get(i).box();double[] values={b.minX,b.minY,b.minZ,b.maxX,b.maxY,b.maxZ};var reference=expected.get(i).getAsJsonArray();for(int j=0;j<6;j++){double old=reference.get(j).getAsDouble(),delta=Math.abs(old-values[j]);if(delta>1e-12)throw new AssertionError("Released Ramp vertex row="+rows+" mode="+row.get("mode")+" material="+material+" cell="+cell+" box="+i+" axis="+j+" expected="+old+" actual="+values[j]);if(Double.doubleToLongBits(old)!=Double.doubleToLongBits(values[j]))drift++;maximum=Math.max(maximum,delta);}boxes++;}snapshots++;
   }}rows++;}}
  if(collisions)System.out.println("Native Ramp bounded collision PASS snapshots="+snapshots+" maximumUnionBytes="+maximumUnionBytes+" maximumUnionNanos="+maximumUnionNanos);
  var unit=new AABB(0,0,0,1,1,1);var origins=new ArrayList<NativeRampGeometry.Origin>();for(int i=0;i<128;i++)origins.add(new NativeRampGeometry.Origin(new BlockPos(i%16,i/16,0),Collections.nCopies(256,unit)));boolean refused=false;long started=System.nanoTime();try{NativeRampGeometry.snapshot(new NativeRampGeometry.Spec(BlockPos.ZERO,Direction.NORTH,0,0,16,1,0,1,0,-2,false,0,false,false,0,false,false,true,origins),.5);}catch(IllegalArgumentException expected){refused=expected.getMessage().contains("work budget");}if(!refused||System.nanoTime()-started>1_000_000_000L)throw new AssertionError("Unbounded complex geometry work");if(rows!=768||snapshots==0||boxes==0)throw new AssertionError("Ramp geometry coverage");System.out.println("Native Ramp geometry PASS Source="+rows+" actualPartSnapshots="+snapshots+" boxes="+boxes+" JDK8/21differentComponents="+drift+" maximumDelta="+maximum+"; fixed source callback corpus, no native movement acceptance");
 }
}
